import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"WhatsApp linked device","description":"","frontmatter":{},"headers":[],"relativePath":"channels/whatsapp.md","filePath":"channels/whatsapp.md"}'),n={name:"channels/whatsapp.md"};function o(p,s,l,r,h,d){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="whatsapp-linked-device" tabindex="-1">WhatsApp linked device <a class="header-anchor" href="#whatsapp-linked-device" aria-label="Permalink to &quot;WhatsApp linked device&quot;">​</a></h1><p>This channel links a WhatsApp account through the Baileys WhatsApp Web bridge. It supports DMs and groups, with multiple numbers per agent. For Meta-issued business credentials and signed webhooks, use the separate <a href="/claude-gateway/channels/whatsapp-cloud.html">WhatsApp Cloud API guide</a>.</p><h2 id="prerequisites-and-credentials" tabindex="-1">Prerequisites and credentials <a class="header-anchor" href="#prerequisites-and-credentials" aria-label="Permalink to &quot;Prerequisites and credentials&quot;">​</a></h2><p>You need a WhatsApp account on a phone you control, access to its <strong>Linked devices</strong> settings, and an existing gateway agent. No developer API key, Meta App Secret or webhook URL is required: the linked device session is the credential.</p><p>The gateway uses an unofficial bridge. Its connect flow discloses account restriction/ban risk; review that before linking a number. The official <a href="https://faq.whatsapp.com/1317564962315842/" target="_blank" rel="noreferrer">WhatsApp device-link instructions</a> explain the phone-side QR process, but do not make Baileys an official WhatsApp integration.</p><h2 id="configure-an-account" tabindex="-1">Configure an account <a class="header-anchor" href="#configure-an-account" aria-label="Permalink to &quot;Configure an account&quot;">​</a></h2><p>Each entry in <code>whatsapp.accounts</code> represents one linked number and its own policy:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;whatsapp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;accounts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Assistant line&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;dmPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;dmAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;groupPolicy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;groupAllowlist&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;requireMention&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;pairing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;sendReadReceipts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;reactionLevel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ack&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Add this to your existing agent entry, keeping the other fields. Use stable filesystem-safe account IDs; do not reuse an ID for another number. An absent/empty account array resolves to the compatibility <code>default</code> account. Older flat WhatsApp configuration is migrated to an accounts array.</p><p>The <code>default</code> account&#39;s linked credentials live in <code>&lt;workspace&gt;/.whatsapp-state/</code>; other accounts use <code>&lt;workspace&gt;/.whatsapp-state/&lt;accountId&gt;/</code>. Preserve these directories across gateway restarts. They are sensitive account sessions, not ordinary cache files.</p><h2 id="link-by-qr-or-device-pairing-code" tabindex="-1">Link by QR or device pairing code <a class="header-anchor" href="#link-by-qr-or-device-pairing-code" aria-label="Permalink to &quot;Link by QR or device pairing code&quot;">​</a></h2><p>Open the agent&#39;s WhatsApp connection settings, select the account slot, and start linking. On the phone, open <strong>Linked devices → Link a device</strong>, scan the gateway&#39;s QR, and wait for the gateway status to become <code>linked</code>.</p><p>For API-driven linking, use a gateway key with write access to the agent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:10850/api/v1/agents/assistant/whatsapp/link</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Api-Key: YOUR_WRITE_KEY&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;account_id&quot;:&quot;default&quot;}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://localhost:10850/api/v1/agents/assistant/whatsapp/status?account_id=default&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;X-Api-Key: YOUR_WRITE_KEY&#39;</span></span></code></pre></div><p>Linking starts asynchronously; poll status to get the QR image and final state. Alternatively, POST <code>/api/v1/agents/assistant/whatsapp/pairing-code</code> with <code>account_id</code> and the account&#39;s <code>phoneNumber</code> in international format, then use WhatsApp&#39;s phone-number device-link flow to enter the resulting code.</p><p>The <strong>device pairing code</strong> links the account to the gateway. A <strong>sender pairing code</strong> in the next step approves someone who messages that account. They serve different purposes.</p><h2 id="approve-messages-and-test" tabindex="-1">Approve messages and test <a class="header-anchor" href="#approve-messages-and-test" aria-label="Permalink to &quot;Approve messages and test&quot;">​</a></h2><p>From another WhatsApp account, send a private text message to the linked number. Compare the sender&#39;s code with the pending entry for this account, then add the sender to its <code>dmAllowlist</code>. Send a second message and verify a reply.</p><p>DM entries accept international numbers or user JIDs ending in <code>@s.whatsapp.net</code>; the access gate normalizes numbers. Group entries are full group JIDs ending in <code>@g.us</code>. Use IDs from the gateway&#39;s pending discovery. The linked number must already belong to a group before it can receive group messages. Approve the group, then mention the linked number when <code>requireMention</code> is true.</p><p>API discovery uses <code>GET /api/v1/agents/assistant/whatsapp/pending?account_id=default</code> with an admin key. To update policies through the agent PATCH API, include <code>whatsapp_account_id</code> plus <code>whatsapp_dm_allowlist</code>, <code>whatsapp_group_allowlist</code> or the other <code>whatsapp_*</code> policy fields. Include existing entries when replacing an allowlist. Link/status routes use <code>account_id</code>; policy PATCH uses <code>whatsapp_account_id</code>.</p><h2 id="supported-behavior" tabindex="-1">Supported behavior <a class="header-anchor" href="#supported-behavior" aria-label="Permalink to &quot;Supported behavior&quot;">​</a></h2><p>Text and inbound images are supported; inbound media downloads have a 20 MB cap. Read receipts default on after access approval. <code>reactionLevel: &quot;ack&quot;</code> adds a processing acknowledgement and clears it when a reply arrives; <code>off</code> suppresses both. Replies preserve the originating account so multiple numbers can have independent conversations and rules.</p><p>Gateway <a href="/claude-gateway/guide/orchestration.html">orchestration</a> applies to this channel&#39;s conversations too. The Telegram/Discord/LINE/Slack voice-note and native voice-control features are not implemented by this linked-device adapter; do not assume enabling agent voice adds WhatsApp audio ingestion.</p><h2 id="troubleshooting-and-reconnecting" tabindex="-1">Troubleshooting and reconnecting <a class="header-anchor" href="#troubleshooting-and-reconnecting" aria-label="Permalink to &quot;Troubleshooting and reconnecting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td><code>pending_scan</code> never becomes <code>linked</code></td><td>QR is current, correct phone scans it, phone approves the device</td></tr><tr><td><code>reconnecting</code></td><td>Outbound connectivity and whether WhatsApp still lists the linked device</td></tr><tr><td>Works until gateway restart</td><td>Account state directory is persisted and readable</td></tr><tr><td>Linked but silent</td><td>Correct account&#39;s DM/group policies, pending approval and group mention</td></tr><tr><td>Policy change affects another number</td><td>Explicit <code>whatsapp_account_id</code> on PATCH and <code>account_id</code> on link/status calls</td></tr><tr><td>Missing old messages</td><td>Test with a new message after linking; linking is not a request to import chat history</td></tr></tbody></table><p><code>POST .../whatsapp/unlink</code> logs out and wipes that account&#39;s session; a new link is required afterward. <code>DELETE .../whatsapp/accounts/:accountId</code> also removes the slot. See <a href="/claude-gateway/api/whatsapp.html">account/link endpoints</a> before automating account removal.</p><p>Implementation references: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/whatsapp/manager.ts" target="_blank" rel="noreferrer">WhatsApp manager</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/config/whatsapp-accounts.ts" target="_blank" rel="noreferrer">account normalization</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/api/whatsapp-access.ts" target="_blank" rel="noreferrer">access gate</a>.</p>`,27)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
